<template><div class="grid"><div class="glass panel"><div class="panel-top"><h3>{{item.id?'Grammar tahrirlash':'Yangi grammar mavzu'}}</h3><button v-if="item.id" class="link-btn" @click="reset">Bekor qilish</button></div><p class="help">Har qatorda bittadan. Examples: <code>English | Uzbek</code>. Exercises: <code>savol | variant1 | variant2 | variant3 | to‘g‘ri javob</code>.</p><form @submit.prevent="$emit('save',{...item})"><div class="row"><label>Level<select v-model.number="item.level"><option v-for="n in 15" :key="n" :value="n">Level {{n}}</option></select></label><label>Mavzu<input v-model.trim="item.title" required placeholder="Past Simple" /></label></div><label>English title<input v-model.trim="item.titleEn" required placeholder="Past Simple Tense" /></label><label>Qoidalar<textarea v-model="item.pointsRaw" rows="5" placeholder="O‘tgan zamonda tugagan harakatlar uchun ishlatiladi..." required></textarea></label><label>Misollar<textarea v-model="item.examplesRaw" rows="4" placeholder="I went home. | Men uyga bordim."></textarea></label><label>Testlar<textarea v-model="item.exercisesRaw" rows="8" placeholder="Yesterday I ___ to school. | go | went | gone | went"></textarea></label><button class="primary" :disabled="saving">{{saving?'Saqlanmoqda…':item.id?'Saqlash':'Grammar qo‘shish'}}</button></form></div><div class="glass panel"><div class="panel-top"><h3>Custom grammar <span>{{items.length}}</span></h3></div><div v-if="!items.length" class="empty">Hali custom grammar yo‘q.</div><div v-for="x in items" :key="x.id" class="item"><div><b>{{x.grammar.title}}</b><span>{{x.grammar.titleEn}}</span><small>Level {{x.grammar.level}} · {{x.grammar.exercises?.length||0}} test</small></div><div class="actions"><button @click="$emit('edit',x)"><i class="ti ti-pencil"></i></button><button class="danger" @click="$emit('delete',x.id)"><i class="ti ti-trash"></i></button></div></div></div></div></template>
<script setup>import {ref,watch} from 'vue';const props=defineProps({items:Array,initial:Object,saving:Boolean});const emit=defineEmits(['save','edit','delete']);const item=ref({...props.initial});watch(()=>props.initial,v=>item.value={...v},{deep:true});function reset(){item.value={level:1,title:'',titleEn:'',pointsRaw:'',examplesRaw:'',exercisesRaw:''}}</script>
<style scoped>@import './editor.css';</style>
